column10:
"{
			Name:        "tool.list",
			Type:        "nats",
			Subject:     "tool.list",
			Description: "Tool discovery request/reply (core NATS). Override to e.g. 'discovery.tool.list' when JetStream streams cover 'tool.>'.",
		}"

"{
					Name:    "entity_stream",
					Type:    "jetstream",
					Subject: "entity.>",
					Config: component.JetStreamPort{
						DeliverPolicy: "all", // Idempotent: catch up on historical entities
					},
				}"

"{
					Name:        "entity_states",
					Type:        "kv-watch",
					Required:    true,
					Description: "Watch entity state changes from ENTITY_STATES KV bucket",
				}"
